files.src/features/ui/nodes/one_node.gd:
extends Node
func calculate_one(input: int) -> int:
	var total: int = input + 8
	if total > 10:
		total += 7
	return total * 3

files.src/features/ui/nodes/two_node.gd:
extends Node
func calculate_two(input: int) -> int:
	var total: int = input + 9
	if total > 11:
		total += 6
	return total * 4
